"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[6365],{6365(e,s,t){t.d(s,{content:()=>u,description:()=>r,keywords:()=>a,title:()=>i});t(5043);var n=t(579);const i="94% des \xe9tudiants utilisent l'IA, et ce n'est pas le probl\xe8me",r="L'enqu\xeate HEPI 2026 montre une utilisation quasi universelle de l'IA parmi les \xe9tudiants britanniques. La v\xe9ritable crise n'est pas l'utilisation de l'IA elle-m\xeame, mais le fait que nous continuons \xe0 \xe9valuer des r\xe9sultats que l'IA peut facilement produire. L'\xe9valuation bas\xe9e sur les processus offre une solution.",a=["IA dans l'\xe9ducation","utilisation IA \xe9tudiants","crise de l'\xe9valuation","\xe9valuation bas\xe9e sur les processus","\xe9valuation r\xe9sistante \xe0 l'IA","\xe9valuation laboratoire virtuel","enqu\xeate HEPI IA 2026","\xe9checs d\xe9tection IA"],u=(0,n.jsxs)(n.Fragment,{children:[(0,n.jsxs)("p",{children:["L'enqu\xeate 2026 du Higher Education Policy Institute sur l'IA g\xe9n\xe9rative des \xe9tudiants est arriv\xe9e la semaine derni\xe8re avec une statistique qui a fait les gros titres : 94% des \xe9tudiants britanniques de premier cycle utilisent maintenant l'IA g\xe9n\xe9rative pour les aider dans leurs travaux \xe9valu\xe9s (",(0,n.jsx)("a",{href:"https://www.hepi.ac.uk/reports/student-generative-ai-survey-2026/",target:"_blank",rel:"noopener noreferrer",children:"HEPI, 2026"}),"). La r\xe9action \xe9tait pr\xe9visible. Certains commentateurs se sont lament\xe9s sur l'int\xe9grit\xe9 acad\xe9mique. D'autres ont r\xe9clam\xe9 des outils de d\xe9tection plus stricts. Quelques-uns ont sugg\xe9r\xe9 d'accepter simplement la d\xe9faite et de laisser l'IA tout \xe9crire."]}),(0,n.jsx)("p",{children:"Toutes ces r\xe9ponses passent \xe0 c\xf4t\xe9 de l'essentiel. Le chiffre de 94% n'est pas la preuve que les \xe9tudiants trichent en masse. C'est la preuve que l'\xe9valuation traditionnelle est bris\xe9e, et ce depuis un certain temps. Nous avons not\xe9 des r\xe9sultats que l'IA peut maintenant produire sans effort, puis nous avons fait mine d'\xeatre surpris quand les \xe9tudiants utilisent l'IA pour les produire. Le probl\xe8me n'est pas les \xe9tudiants. Le probl\xe8me est que nous avons \xe9valu\xe9 les mauvaises choses."}),(0,n.jsx)("h2",{children:"Que montre r\xe9ellement l'enqu\xeate HEPI ?"}),(0,n.jsx)("p",{children:"Le rapport HEPI, r\xe9alis\xe9 par Savanta en d\xe9cembre 2025 aupr\xe8s de 1 054 \xe9tudiants britanniques \xe0 temps plein, r\xe9v\xe8le une image plus nuanc\xe9e que le titre ne le sugg\xe8re. Oui, 94% utilisent l'IA pour les aider dans leurs travaux \xe9valu\xe9s. Mais \"aider\" couvre un large spectre : r\xe9sumer des lectures denses, g\xe9n\xe9rer des \xe9bauches de plans, expliquer des concepts difficiles et v\xe9rifier la grammaire. Seulement 12% d\xe9clarent inclure directement du texte g\xe9n\xe9r\xe9 par l'IA dans leurs soumissions, contre 8% l'ann\xe9e pr\xe9c\xe9dente."}),(0,n.jsx)("p",{children:"Les r\xe9ponses qualitatives sont particuli\xe8rement r\xe9v\xe9latrices. Un \xe9tudiant a expliqu\xe9 que \"les outils d'IA m'ont permis de r\xe9sumer rapidement des lectures denses et de g\xe9n\xe9rer des brouillons ou des plans pour les devoirs, \xe9conomisant des heures de travail fastidieux et me permettant de me concentrer sur l'analyse critique et une compr\xe9hension plus profonde.\" Un autre a simplement admis : \"Je n'utilise pas du tout mon cerveau.\" Les auteurs de HEPI notent le contraste frappant : \"Il y a une diff\xe9rence entre un \xe9tudiant qui utilise l'IA pour faire avancer son apprentissage et un \xe9tudiant qui externalise son apprentissage \xe0 l'IA.\""}),(0,n.jsx)("p",{children:"Cette distinction compte. Le premier \xe9tudiant utilise l'IA comme \xe9chafaudage cognitif, lib\xe9rant des ressources mentales pour une r\xe9flexion de niveau sup\xe9rieur. Le second vit ce que l'OCDE appelle le \"d\xe9chargement cognitif\", laissant l'IA faire la r\xe9flexion et manquant la lutte n\xe9cessaire \xe0 un apprentissage authentique. Les deux comportements sont enregistr\xe9s comme \"utilisation de l'IA\", mais leurs implications \xe9ducatives sont oppos\xe9es."}),(0,n.jsx)("h2",{children:"Pourquoi la d\xe9tection ne peut pas r\xe9soudre ce probl\xe8me"}),(0,n.jsx)("p",{children:"La r\xe9ponse instinctive \xe0 l'augmentation de l'utilisation de l'IA est d'am\xe9liorer la d\xe9tection. Si les \xe9tudiants utilisent l'IA de mani\xe8re inappropri\xe9e, attrapez-les. Mais cette approche a \xe9chou\xe9, \xe9choue et continuera d'\xe9chouer pour des raisons maintenant bien document\xe9es."}),(0,n.jsxs)("p",{children:["Des analyses ind\xe9pendantes ont r\xe9v\xe9l\xe9 que les outils de d\xe9tection d'IA produisent des taux de faux positifs entre 5% et 20%, ce qui signifie que le travail authentique des \xe9tudiants est r\xe9guli\xe8rement signal\xe9 comme g\xe9n\xe9r\xe9 par une machine (",(0,n.jsx)("a",{href:"https://nmllplaw.com/blog/when-ai-gets-you-accused-what-to-do-if-your-school-says-you-used-chatgpt/",target:"_blank",rel:"noopener noreferrer",children:"Nesenoff & Miltenberg, 2025"}),"). Les cons\xe9quences ne sont pas abstraites. En 2024, l'Australian Catholic University a faussement accus\xe9 environ 1 500 \xe9tudiants sur la base du d\xe9tecteur d'IA de Turnitin. Des \xe9tudiants ont perdu des postes d'infirmiers dipl\xf4m\xe9s. Les relev\xe9s de notes ont \xe9t\xe9 marqu\xe9s \"r\xe9sultats retenus\" pendant des mois. Certains ont \xe9t\xe9 forc\xe9s de remettre tout leur historique de navigation internet pour prouver leur innocence."]}),(0,n.jsx)("p",{children:"Ces outils sont particuli\xe8rement peu fiables pour les locuteurs non natifs de l'anglais et les \xe9tudiants neurodivergents, dont les mod\xe8les d'\xe9criture peuvent naturellement diff\xe9rer de ce que les algorithmes attendent de l'\"\xe9criture humaine\". Un \xe9tudiant de la Yale School of Management a intent\xe9 un proc\xe8s en 2025 all\xe9guant une suspension injustifi\xe9e apr\xe8s que GPTZero ait signal\xe9 son examen, citant une discrimination contre les locuteurs non natifs de l'anglais. La course aux armements de la d\xe9tection n'est pas seulement inefficace ; elle nuit activement aux \xe9tudiants qu'elle pr\xe9tend prot\xe9ger."}),(0,n.jsx)("p",{children:"M\xeame lorsque la d\xe9tection fonctionne, elle ne traite que le sympt\xf4me. Un \xe9tudiant qui \xe9chappe avec succ\xe8s \xe0 la d\xe9tection n'a toujours rien appris du devoir. Un \xe9tudiant qui est pris a \xe9t\xe9 puni, mais la structure d'incitation sous-jacente reste inchang\xe9e. Tant que nous \xe9valuons des r\xe9sultats que l'IA peut produire, nous incitons les \xe9tudiants \xe0 utiliser l'IA pour les produire. La d\xe9tection traite le comportement comme un \xe9chec moral alors qu'il s'agit en r\xe9alit\xe9 d'une r\xe9ponse rationnelle \xe0 des incitations mal align\xe9es."}),(0,n.jsx)("h2",{children:"Le vrai probl\xe8me : \xc9valuer des r\xe9sultats qui ne n\xe9cessitent plus de r\xe9flexion humaine"}),(0,n.jsx)("p",{children:"La dissertation traditionnelle, le rapport de laboratoire, l'ensemble de probl\xe8mes : ces formats d'\xe9valuation ont \xe9volu\xe9 quand les produire n\xe9cessitait un effort cognitif soutenu. Si vous vouliez un argument bien structur\xe9 sur la photosynth\xe8se, vous deviez comprendre la photosynth\xe8se. Si vous vouliez une analyse coh\xe9rente des r\xe9sultats de titrage, vous deviez effectuer le titrage et r\xe9fl\xe9chir aux donn\xe9es. Le r\xe9sultat servait de preuve raisonnable du processus."}),(0,n.jsx)("p",{children:"Cette corr\xe9lation s'est bris\xe9e. Un \xe9tudiant peut maintenant demander \xe0 une IA de g\xe9n\xe9rer une dissertation sophistiqu\xe9e, compl\xe8te avec des citations, en moins d'une minute. Il peut demander un rapport de laboratoire avec des observations plausibles, une analyse d'erreurs appropri\xe9e et des conclusions bien raisonn\xe9es sans toucher aucun \xe9quipement. Le r\xe9sultat semble correct parce que l'IA peut synth\xe9tiser \xe0 quoi ressemblent les r\xe9sultats corrects. Mais l'\xe9tudiant n'a d\xe9velopp\xe9 aucune des comp\xe9tences que le devoir \xe9tait cens\xe9 enseigner."}),(0,n.jsx)("p",{children:"Ce n'est pas un nouveau probl\xe8me. Les \xe9tudiants ont toujours trouv\xe9 des moyens de raccourcir les \xe9valuations : copier des ann\xe9es pr\xe9c\xe9dentes, diviser le travail entre groupes d'\xe9tude, acheter des dissertations en ligne. L'IA a simplement d\xe9mocratis\xe9 le raccourci, le rendant accessible \xe0 tous plut\xf4t qu'\xe0 ceux qui ont des ressources ou des connexions. L'\xe9chelle a chang\xe9, mais le probl\xe8me sous-jacent, que nous \xe9valuons des r\xe9sultats d\xe9tach\xe9s du processus, existe depuis des d\xe9cennies."}),(0,n.jsx)("h2",{children:"\xc0 quoi ressemble une \xe9valuation r\xe9sistante \xe0 l'IA ?"}),(0,n.jsxs)("p",{children:["Les Perspectives de l'\xe9ducation num\xe9rique de l'OCDE 2026 ont r\xe9pondu \xe0 cette question explicitement : \"Au lieu de noter le travail final, les enseignants devraient \xe9valuer comment un \xe9tudiant a interagi avec l'IA, comment il a critiqu\xe9 ses r\xe9sultats et comment il a affin\xe9 ses id\xe9es au fil du temps\" (",(0,n.jsx)("a",{href:"https://www.oecd.org/en/publications/oecd-digital-education-outlook-2026_062a7394-en.html",target:"_blank",rel:"noopener noreferrer",children:"OCDE, 2026"}),"). C'est l'\xe9valuation orient\xe9e processus : \xe9valuer non pas ce que les \xe9tudiants produisent, mais comment ils s'engagent dans l'apprentissage pour le produire."]}),(0,n.jsx)("p",{children:"En pratique, cela signifie capturer le processus lui-m\xeame. Quand un \xe9tudiant travaille sur un probl\xe8me, quelles d\xe9cisions prend-il ? Quand il rencontre une difficult\xe9, comment r\xe9agit-il ? Quand sa premi\xe8re approche \xe9choue, s'adapte-t-il ou abandonne-t-il ? Ces questions touchent \xe0 ce que l'\xe9ducation vise r\xe9ellement \xe0 d\xe9velopper : les comp\xe9tences de r\xe9flexion, la capacit\xe9 de r\xe9solution de probl\xe8mes et la capacit\xe9 d'apprendre de ses erreurs."}),(0,n.jsx)("p",{children:"La science de laboratoire offre un exemple particuli\xe8rement clair. Vous ne pouvez pas utiliser l'IA pour ma\xeetriser la technique de pipetage. Vous ne pouvez pas demander \xe0 ChatGPT de d\xe9velopper votre motricit\xe9 fine, votre capacit\xe9 \xe0 observer des changements subtils de couleur, ou votre instinct pour quand une exp\xe9rience semble mal tourner. Ces comp\xe9tences existent dans le corps et se d\xe9veloppent par la pratique. Un \xe9tudiant qui regarde l'IA g\xe9n\xe9rer un rapport de laboratoire parfait n'a rien appris sur le travail en laboratoire."}),(0,n.jsx)("h2",{children:"Comment les laboratoires virtuels rendent possible l'\xe9valuation des processus"}),(0,n.jsx)("p",{children:"Chez WhimsyLabs, l'\xe9valuation orient\xe9e processus n'est pas une adaptation en r\xe9ponse \xe0 l'IA. C'est ainsi que nous avons con\xe7u notre plateforme d\xe8s le d\xe9but. Nos laboratoires virtuels capturent chaque action qu'un \xe9tudiant effectue : quel \xe9quipement il s\xe9lectionne, dans quel ordre il effectue les \xe9tapes, comment il r\xe9pond \xe0 des r\xe9sultats inattendus et comment sa technique s'am\xe9liore au fil du temps. Cette journalisation des interactions cr\xe9e un enregistrement d\xe9taill\xe9 de la pens\xe9e scientifique en action."}),(0,n.jsxs)("p",{children:[(0,n.jsx)("strong",{children:"La journalisation des actions"})," est le fondement. Quand un \xe9tudiant pipette une solution, nous suivons sa technique : l'angle auquel il tient la pipette, la vitesse \xe0 laquelle il distribue, s'il pr\xe9humidifie l'embout. Quand il mesure la temp\xe9rature, nous enregistrons non seulement la lecture finale mais quand il l'a prise, combien de lectures il a faites et s'il a attendu l'\xe9quilibre. Ces d\xe9tails granulaires r\xe9v\xe8lent si un \xe9tudiant d\xe9veloppe des habitudes de laboratoire appropri\xe9es ou passe simplement par les mouvements."]}),(0,n.jsxs)("p",{children:[(0,n.jsx)("strong",{children:"La notation de la technique"})," s'appuie sur la journalisation des actions pour \xe9valuer la comp\xe9tence proc\xe9durale. Un \xe9tudiant qui atteint le bon point final dans un titrage par une technique b\xe2cl\xe9e re\xe7oit un retour diff\xe9rent de celui dont la technique \xe9tait pr\xe9cise mais qui a mal calcul\xe9 la molarit\xe9. Les deux doivent s'am\xe9liorer, mais de diff\xe9rentes mani\xe8res. L'\xe9valuation traditionnelle, concentr\xe9e uniquement sur la r\xe9ponse finale, ne peut pas les distinguer."]}),(0,n.jsxs)("p",{children:[(0,n.jsx)("strong",{children:"La comparaison des parcours experts"})," place le comportement de l'\xe9tudiant en contexte. Nous avons cartographi\xe9 comment les scientifiques experts abordent les exp\xe9riences courantes, identifiant les arbres de d\xe9cision et les mod\xe8les de r\xe9solution de probl\xe8mes qui caract\xe9risent la pens\xe9e scientifique comp\xe9tente. Quand l'approche d'un \xe9tudiant diverge significativement des parcours experts, cela signale une opportunit\xe9 de guidage cibl\xe9. Quand son approche s'aligne avec le raisonnement expert m\xeame s'il arrive \xe0 une conclusion incorrecte, cela sugg\xe8re que sa pens\xe9e scientifique se d\xe9veloppe de mani\xe8re appropri\xe9e."]}),(0,n.jsx)("h2",{children:"La crise de l'\xe9valuation est aussi une opportunit\xe9"}),(0,n.jsx)("p",{children:"L'enqu\xeate HEPI r\xe9v\xe8le quelque chose qui devrait pr\xe9occuper tout \xe9ducateur : pr\xe8s des deux tiers des \xe9tudiants (65%) disent que l'\xe9valuation a consid\xe9rablement chang\xe9 en r\xe9ponse \xe0 l'IA, et beaucoup articulent une anxi\xe9t\xe9 concernant les fausses accusations de mauvaise conduite. Les \xe9tudiants vivent dans un environnement de surveillance o\xf9 leur travail authentique pourrait \xeatre signal\xe9 comme frauduleux, tandis que le travail assist\xe9 par l'IA pourrait passer inaper\xe7u. Les incitations sont perverses."}),(0,n.jsx)("p",{children:"Mais la m\xeame enqu\xeate montre une voie \xe0 suivre. Les \xe9tudiants voient massivement les comp\xe9tences en IA comme essentielles, 68% croyant que ces capacit\xe9s sont n\xe9cessaires pour prosp\xe9rer dans le monde d'aujourd'hui. Ils n'essaient pas de tricher. Ils essaient de d\xe9velopper des comp\xe9tences qu'ils per\xe7oivent correctement comme importantes. Le probl\xe8me est que les structures d'\xe9valuation actuelles les obligent \xe0 choisir entre d\xe9velopper la litt\xe9ratie en IA et d\xe9montrer des connaissances disciplinaires, alors que les deux devraient \xeatre possibles simultan\xe9ment."}),(0,n.jsx)("p",{children:"L'\xe9valuation orient\xe9e processus r\xe9sout cette tension. Quand nous \xe9valuons comment les \xe9tudiants pensent plut\xf4t que ce qu'ils produisent, l'IA devient un outil plut\xf4t qu'une menace. Les \xe9tudiants peuvent utiliser l'IA pour r\xe9sumer des lectures, g\xe9n\xe9rer des \xe9bauches de plans ou v\xe9rifier leur raisonnement, tout en \xe9tant toujours \xe9valu\xe9s sur le travail cognitif qui compte : formuler des hypoth\xe8ses, interpr\xe9ter des donn\xe9es, s'adapter \xe0 des r\xe9sultats inattendus et d\xe9velopper des comp\xe9tences de laboratoire physiques qu'aucune IA ne peut reproduire."}),(0,n.jsx)("h2",{children:"Ce que cela signifie pour l'enseignement des sciences"}),(0,n.jsx)("p",{children:"L'enseignement des sciences fait face \xe0 un d\xe9fi particulier parce que les comp\xe9tences de laboratoire sont centrales \xe0 la discipline. Un \xe9tudiant qui n'a jamais tenu une pipette, ajust\xe9 un microscope ou observ\xe9 une r\xe9action chimique ne peut pas pr\xe9tendre comprendre la science dans un sens significatif. Pourtant, l'\xe9valuation traditionnelle de laboratoire, concentr\xe9e sur les rapports \xe9crits, a toujours \xe9t\xe9 vuln\xe9rable aux raccourcis. L'IA a simplement rendu la vuln\xe9rabilit\xe9 impossible \xe0 ignorer."}),(0,n.jsx)("p",{children:"La solution n'est pas d'interdire l'IA de l'enseignement des sciences. C'est d'\xe9valuer ce que l'IA ne peut pas faire : les comp\xe9tences physiques, la comp\xe9tence proc\xe9durale, la capacit\xe9 de r\xe9pondre aux d\xe9fis exp\xe9rimentaux en temps r\xe9el. Les laboratoires virtuels qui capturent les donn\xe9es de processus rendent cela possible \xe0 grande \xe9chelle. Le journal d'interactions d'un \xe9tudiant fournit des preuves plus riches de son d\xe9veloppement scientifique que n'importe quel rapport \xe9crit pourrait le faire, et il ne peut \xeatre falsifi\xe9 par aucune IA."}),(0,n.jsx)("p",{children:"Les auteurs de HEPI concluent que \"les institutions ont un r\xf4le crucial \xe0 jouer pour s'assurer que l'IA am\xe9liore l'apprentissage plut\xf4t que de le diminuer.\" Ils recommandent une initiation structur\xe9e \xe0 l'IA, des changements de programmes pour enseigner explicitement les comp\xe9tences en IA et des orientations claires sp\xe9cifiques \xe0 l'\xe9valuation. Tout cela est important. Mais le changement le plus fondamental requis est de repenser ce que nous \xe9valuons en premier lieu."}),(0,n.jsx)("p",{children:"Quatre-vingt-quatorze pour cent des \xe9tudiants utilisant l'IA n'est pas une crise. C'est un signal que l'\xe9valuation doit \xe9voluer. Les outils existent. La recherche le soutient. La seule question est de savoir si l'\xe9ducation s'adaptera, ou continuera \xe0 mener une guerre de d\xe9tection qu'elle a d\xe9j\xe0 perdue."}),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)("h2",{children:"Articles connexes"}),(0,n.jsxs)("ul",{children:[(0,n.jsx)("li",{children:(0,n.jsx)("a",{href:"/fr/blog/oecd-process-oriented-assessment-validation",children:"L'OCDE dit : \xc9valuez le processus, pas le produit"})}),(0,n.jsx)("li",{children:(0,n.jsx)("a",{href:"/fr/blog/ai-text-grading-fails-process-assessment-works",children:"Pourquoi la notation de texte par IA \xe9choue et l'\xe9valuation des processus fonctionne"})}),(0,n.jsx)("li",{children:(0,n.jsx)("a",{href:"/fr/blog/process-based-lab-assessment-future",children:"Noter le processus, pas la r\xe9ponse : L'avenir de l'\xe9valuation en laboratoire"})}),(0,n.jsx)("li",{children:(0,n.jsx)("a",{href:"/fr/blog/ai-assessment-crisis-solution",children:"IA et la crise de l'\xe9valuation : Une solution pratique"})})]})]}),(0,n.jsxs)("div",{className:"references-section",children:[(0,n.jsx)("h3",{children:"R\xe9f\xe9rences"}),(0,n.jsxs)("ul",{className:"references-list",children:[(0,n.jsxs)("li",{children:["Higher Education Policy Institute (HEPI). (2026). Student Generative AI Survey 2026. HEPI Report 199."," ",(0,n.jsx)("a",{href:"https://www.hepi.ac.uk/reports/student-generative-ai-survey-2026/",target:"_blank",rel:"noopener noreferrer",children:"https://www.hepi.ac.uk/reports/student-generative-ai-survey-2026/"})]},"ref-1"),(0,n.jsxs)("li",{children:["Nesenoff & Miltenberg LLP. (2025). When AI Gets You Accused: What to Do if Your School Says You Used ChatGPT."," ",(0,n.jsx)("a",{href:"https://nmllplaw.com/blog/when-ai-gets-you-accused-what-to-do-if-your-school-says-you-used-chatgpt/",target:"_blank",rel:"noopener noreferrer",children:"https://nmllplaw.com/blog/when-ai-gets-you-accused-what-to-do-if-your-school-says-you-used-chatgpt/"})]},"ref-2"),(0,n.jsxs)("li",{children:["OCDE. (2026). OECD Digital Education Outlook 2026: Exploring Effective Uses of Generative AI in Education. OECD Publishing."," ",(0,n.jsx)("a",{href:"https://www.oecd.org/en/publications/oecd-digital-education-outlook-2026_062a7394-en.html",target:"_blank",rel:"noopener noreferrer",children:"https://www.oecd.org/en/publications/oecd-digital-education-outlook-2026_062a7394-en.html"})]},"ref-3")]})]})]})}}]);
